grant select on public.curricula,public.courses_or_levels,public.subjects,public.units,public.topics,public.learning_objectives,public.content_items,public.content_versions,public.questions,public.question_versions,public.question_objectives,public.mark_schemes to authenticated;
grant select,insert,update on public.practice_sessions,public.practice_session_questions,public.exam_sessions,public.exam_session_questions,public.attempts,public.attempt_answers,public.learner_objective_states to authenticated;
